package techguns.gametest;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.gametest.*;
import techguns.*;
import techguns.machines.*;
@GameTestHolder(Techguns.MODID) @PrefixGameTestTemplate(false)
public final class FabricatorGameTests {
    @GameTest(template="empty") public static void automationReconnectsAfterControllerCapabilitiesAreRevived(GameTestHelper h){var m=controller(h);parts(h,m,Direction.NORTH);m.formStructure(Direction.NORTH);var pos=m.structureParts(Direction.NORTH).entrySet().stream().filter(e->!e.getValue()).findFirst().orElseThrow().getKey();var part=(MachinePartEntity)h.getLevel().getBlockEntity(pos);var old=part.getCapability(ForgeCapabilities.ENERGY);h.assertTrue(old.isPresent(),"Formed housing exposes energy");m.invalidateCaps();h.assertFalse(old.isPresent(),"Invalidating the controller invalidates retained automation handles");m.reviveCaps();var replacement=part.getCapability(ForgeCapabilities.ENERGY);h.assertTrue(replacement.isPresent()&&replacement!=old,"A housing replaces its invalid cached handle after controller revival");replacement.orElseThrow(IllegalStateException::new).receiveEnergy(500,false);h.assertTrue(m.energy.getEnergyStored()==500,"Reconnected automation delivers energy to the current controller");h.succeed();}
    @GameTest(template="empty") public static void stalePartLinksRestoreTheirVisibleUnformedState(GameTestHelper h){var m=controller(h);parts(h,m,Direction.NORTH);m.formStructure(Direction.NORTH);var pos=m.structureParts(Direction.NORTH).keySet().iterator().next();var part=(MachinePartEntity)h.getLevel().getBlockEntity(pos);m.formed=false;h.assertTrue(part.linked()&&part.getBlockState().getValue(MachineBlock.FORMED),"The test reproduces a part whose controller unformed while it was unavailable");part.validateLink();h.assertTrue(!part.linked()&&!part.getBlockState().getValue(MachineBlock.FORMED),"Reloaded stale parts unlink and recover their standalone visible block model");h.succeed();}
    private static ProcessingMachine controller(GameTestHelper h){h.setBlock(2,1,2,TGMachines.BLOCKS.get(MachineKind.FABRICATOR).get());return (ProcessingMachine)h.getBlockEntity(new BlockPos(2,1,2));}
    private static void parts(GameTestHelper h,ProcessingMachine m,Direction direction){for(var entry:m.structureParts(direction).entrySet())h.getLevel().setBlockAndUpdate(entry.getKey(),(entry.getValue()?TGFabricator.GLASS:TGFabricator.HOUSING).get().defaultBlockState());}
    private static void energyCellInputs(ProcessingMachine m){m.inventory.setStackInSlot(0,new ItemStack(Items.GOLD_INGOT));m.inventory.setStackInSlot(1,TGItems.WIRE_COPPER.get().getDefaultInstance());m.inventory.setStackInSlot(2,new ItemStack(Items.REDSTONE,3));m.inventory.setStackInSlot(3,TGItems.PLASTIC_SHEET.get().getDefaultInstance());}
    @GameTest(template="empty") public static void fabricatorFormsInAllFourHorizontalDirections(GameTestHelper h){for(var direction:Direction.Plane.HORIZONTAL){for(int x=0;x<5;x++)for(int z=0;z<5;z++)for(int y=1;y<4;y++)h.setBlock(x,y,z,Blocks.AIR);var m=controller(h);parts(h,m,direction);h.assertTrue(m.formStructure(direction)&&m.formed,"Source two-by-two-by-two construction forms toward every horizontal face");h.assertTrue(m.structureParts(direction).size()==7,"Fabricator requires three housing blocks and four glass blocks around its controller");m.unformStructure();h.assertFalse(m.formed,"Unforming restores all linked construction blocks");}h.succeed();}
    @GameTest(template="empty") public static void incompleteFabricatorCannotProduceItems(GameTestHelper h){var m=controller(h);parts(h,m,Direction.NORTH);var glass=m.structureParts(Direction.NORTH).entrySet().stream().filter(java.util.Map.Entry::getValue).findFirst().orElseThrow().getKey();h.getLevel().setBlockAndUpdate(glass,Blocks.AIR.defaultBlockState());h.assertFalse(m.formStructure(Direction.NORTH),"Missing glass rejects construction");energyCellInputs(m);m.setEnergy(8000);m.tick();h.assertTrue(!m.running()&&!m.inventory.getStackInSlot(0).isEmpty()&&m.energy.getEnergyStored()==8000,"An incomplete machine cannot reserve inputs or consume energy");h.succeed();}
    @GameTest(template="empty") public static void allSixFabricatorRecipesUseOriginalInputsAndEnergy(GameTestHelper h){var m=controller(h);parts(h,m,Direction.NORTH);m.formStructure(Direction.NORTH);int count=0;for(var recipe:MachineRecipes.all())if(recipe.kind()==MachineKind.FABRICATOR){for(int slot=0;slot<4;slot++){var values=recipe.ingredients()[slot].getItems();h.assertTrue(values.length>0,"Every standalone fabricator ingredient tag must resolve");m.inventory.setStackInSlot(slot,values[0].copyWithCount(recipe.amounts()[slot]));}m.inventory.setStackInSlot(4,ItemStack.EMPTY);m.setEnergy(8000);m.tick();for(int i=0;i<100;i++)m.tick();h.assertTrue(ItemStack.matches(m.inventory.getStackInSlot(4),recipe.result())&&m.energy.getEnergyStored()==0,"Fabricator uses source output, 100 ticks and 8000 FE");count++;}h.assertTrue(count>=6,"All six source fabricator recipes are available");h.succeed();}
    @GameTest(template="empty") public static void brokenStructurePausesOperationAndInvalidatesSlaveAutomation(GameTestHelper h){var m=controller(h);parts(h,m,Direction.NORTH);m.formStructure(Direction.NORTH);var housing=m.structureParts(Direction.NORTH).entrySet().stream().filter(e->!e.getValue()).findFirst().orElseThrow().getKey();var part=(MachinePartEntity)h.getLevel().getBlockEntity(housing);var energy=part.getCapability(ForgeCapabilities.ENERGY);h.assertTrue(energy.isPresent(),"Housing exposes the formed controller energy input");energy.orElseThrow(IllegalStateException::new).receiveEnergy(8000,false);energyCellInputs(m);m.tick();for(int i=0;i<40;i++)m.tick();h.getLevel().setBlockAndUpdate(housing,Blocks.AIR.defaultBlockState());m.tick();h.assertTrue(!m.formed&&m.running()&&m.progress==40&&m.energy.getEnergyStored()==4800,"Broken structure pauses the in-flight operation without discarding ingredients");h.assertFalse(energy.isPresent(),"Unlinking invalidates previously cached slave capabilities");parts(h,m,Direction.NORTH);h.assertTrue(m.formStructure(Direction.NORTH),"Restoring the same blocks allows the structure to form again");for(int i=40;i<100;i++)m.tick();h.assertTrue(m.inventory.getStackInSlot(4).is(TGItems.ENERGY_CELL_EMPTY.get())&&m.energy.getEnergyStored()==0,"Reforming resumes the original transaction once");h.succeed();}
    @GameTest(template="empty") public static void templateSelectionDecidesWhatTheInputSlotsAccept(GameTestHelper h){var m=controller(h);var gold=new ItemStack(Items.GOLD_INGOT);h.assertFalse(m.accepts(0,gold),"Without a template the fabricator takes no inputs");int index=-1;var list=MachineRecipes.fabricator();for(int i=0;i<list.size();i++)if(list.get(i).ingredients()[0].test(gold)){index=i;break;}h.assertTrue(index>=0,"A gold based fabricator recipe exists");m.button(10+index);h.assertTrue(m.fabricatorRecipe==index&&m.accepts(0,gold),"The chosen template accepts its own inputs");h.assertFalse(m.accepts(0,new ItemStack(Items.DIRT)),"Foreign items stay out");m.button(9);h.assertFalse(m.accepts(0,gold),"Clearing the template locks the slots again");h.succeed();}
}
